package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;

/**
 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then), and
 * the number of the claim it corrects (null unless it is a correction), and the date it rounds on: its own, or for
 * a correction the date of the claim it corrects, and its number within its period (<period>-<n>, or X-<n> in no
 * period) when it was opened while the sheet numbered by period, in place of a number on the sheet (null otherwise),
 * and its due-by (yyyy-MM-dd), fixed when it was added from the terms of its person's grade in force on its date,
 * and its status log, oldest first.
 */
public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String periodNumber, String dueBy, List<ClaimLogLine> log) {

    /** Whether this claim is a correction: a negative amount, naming the number (as it shows) of the settled claim it corrects. */
    public boolean correction() {
        return amount.startsWith("-");
    }

    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount + " date=" + date;
    }

    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
    public Claim withNumber(Integer number) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log);
    }

    /** This claim, numbered within its period: its audit fields end with number=<period number>. */
    public Claim withPeriodNumber(String periodNumber) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log);
    }

    /** This claim, settled with its due fixed (null when its grade had no rate). */
    public Claim withSettledDue(String settledDue) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log);
    }

    /** This claim, with its status log (oldest first). */
    public Claim withLog(List<ClaimLogLine> log) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log);
    }

    /** The number the claim shows: its number within its period, else its number on the sheet; null for none. */
    public String shownNumber() {
        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
    }

    /** The audit fields of a status change: {@link #auditFields} then number=<number> when it has one. */
    public String statusAuditFields(String person) {
        String shown = shownNumber();
        return auditFields(person) + (shown == null ? "" : " number=" + shown);
    }

    /** Whether this claim counts toward the totals: OPEN, PENDING and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.PENDING || status == ClaimStatus.SETTLED;
    }

    /** Whether this claim's statement binds its figure: it is stated, and not PENDING (which shows its live figure). */
    public boolean bound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** Whether this claim counts toward the live totals when its person is {@code held}: then only SETTLED does. */
    public boolean counts(boolean held) {
        return held ? status == ClaimStatus.SETTLED : counts();
    }

    /**
     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
     * settled or bound when its grade had no rate keeps none; a PENDING claim is not bound).
     */
    public boolean fixed() {
        return settledDue != null || (bound() && statedDue != null);
    }

    /**
     * This claim's due: its {@link #figure} plus, while it is overdue, its late charge (settling fixes the charge
     * in); null when there is no figure.
     */
    public BigDecimal due(List<Rate> rates, String grade, BigDecimal floor, Late late) {
        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
        return figure == null || settledDue != null ? figure : figure.add(late.charge(this, figure));
    }

    /**
     * This claim's figure: the due fixed when settled, else the one its statement bound (unless PENDING), else its amount at the
     * grade's rate in force on its date, raised to at least the sheet's floor (a correction has no floor); null when
     * there is none.
     */
    public BigDecimal figure(List<Rate> rates, String grade, BigDecimal floor) {
        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
    }

    /** This claim's {@link #figure}, its live figure rounded by the mode. */
    public BigDecimal figure(List<Rate> rates, String grade, BigDecimal floor, RoundingMode rounding) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (bound()) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        BigDecimal live = Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
        return live == null || correction() ? live : live.max(floor);
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.rate.Rate;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. While held, their OPEN claims count in no live total.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, boolean held,
        List<GradeFrom> grades) {

    /** Whether a claim dated {@code date} is after this person's retirement, and so refused. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), or one at another grade, in force on its date. Their due-total is n/a only when no claim does and
     * that grade has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, BigDecimal floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null);
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, each with their grades by from-date. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, name, version, retired_from, held FROM person";

    private record Row(long id, String name, long version, String retiredFrom, boolean held) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;

    public People(JdbcTemplate jdbc, SheetClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    private List<Person> query(String sheet, String where, Object... args) {
        List<Row> rows = jdbc.query(COLUMNS + " " + where, (rs, i) -> new Row(rs.getLong("id"), rs.getString("name"),
                rs.getLong("version"),
                rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
                rs.getBoolean("held")), args);
        if (rows.isEmpty()) {
            return List.of();
        }
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person p ON p.id = g.person_id"
                + " WHERE p.sheet = ? ORDER BY g.person_id, g.from_key", (rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"),
                                    rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString()));
                }, sheet);
        LocalDate today = clock.today(sheet);
        List<Person> people = new ArrayList<>();
        for (Row r : rows) {
            List<GradeFrom> mine = List.copyOf(grades.getOrDefault(r.id(), List.of()));
            people.add(new Person(r.id(), r.name(), Person.gradeOn(mine, today), r.version(), r.retiredFrom(), r.held(),
                    mine));
        }
        return people;
    }

    /** Everyone on the sheet, in the order they were added. */
    public List<Person> list(String sheet) {
        return query(sheet, "WHERE sheet = ? ORDER BY id", sheet);
    }

    public Person find(String sheet, long id) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND id = ?", sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case; null when there is none. */
    public Person findByName(String sheet, String name) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND name_key = LOWER(?)", sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    private boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
        return taken != null && taken > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time. */
    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
        if (nameTaken(sheet, name, null)) {
            throw new DuplicatePersonNameException(name);
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            insert(sheet, name, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        long id = keys.getKey().longValue();
        setGrade(id, grade, null);
        return find(sheet, id);
    }

    private void insert(String sheet, String name, GeneratedKeyHolder keys) {
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet, name) VALUES (?, ?)", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setString(2, name);
            return ps;
        }, keys);
    }

    /** Records the person's grade from the from-date (null: from the beginning of time), replacing the one there for it. */
    public void setGrade(long id, String grade, LocalDate from) {
        Date date = from == null ? null : Date.valueOf(from);
        if (jdbc.update("UPDATE person_grade SET grade = ? WHERE person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                grade, id, date) == 0) {
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, ?)", id, grade, date);
        }
    }

    /** Retire the person from the date. */
    public void retire(String sheet, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet = ? AND id = ?", Date.valueOf(from), sheet, id);
    }

    /** Put the person on hold, or take them off it. */
    public void hold(String sheet, long id, boolean held) {
        jdbc.update("UPDATE person SET held = ? WHERE sheet = ? AND id = ?", held, sheet, id);
    }

    /** Save the person's name over the version it carries, raising the version; refused when it has moved on. */
    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
        if (nameTaken(sheet, person.name(), person.id())) {
            throw new DuplicatePersonNameException(person.name());
        }
        int updated;
        try {
            updated = jdbc.update(
                    "UPDATE person SET name = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
                    person.name(), sheet, person.id(), person.version());
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(person.name());
        }
        if (updated == 0) {
            throw new StalePersonException(person.id());
        }
    }
}

